import os
import requests

def safety_threshold(payload, config=None):
    config = config or {}
    client = requests.Session()
    api_host = "https://api.openai.com/v1/moderations"
    category_thresholds = config.get("category_thresholds", {
        "hate": 0.2,
        "self_harm": 0.2,
        "sexual": 0.2,
        "violence": 0.2
    })
    headers = {
        "Authorization": f"Bearer {os.getenv('OPENAI_API_KEY')}",
        "Content-Type": "application/json"
    }
    response = client.post(api_host, json=payload, headers=headers)
    data = response.json()
    result = {"flagged": False, "categories": {}}
    for category, scores in data["results"][0]["categories"].items():
        threshold = category_thresholds.get(category.lower(), 0.0)
        result["categories"][category] = scores
        if scores >= threshold:
            result["flagged"] = True
    return result
